class Charger {
    String color;
    String brand;
}

class OS {
    int type;
    String name;
}

class Mobile {
    String color;
    String brand;

    OS os;
    Charger ref;
}

class Charger {
    String color;
    String brand;

    Charger(String color, String brand) {
        this.color = color;
        this.brand = brand;
    }
}

class OS {
    int type;
    String name;

    OS(int type, String name) {
        this.type = type;
        this.name = name;
    }
}

class Mobile {
    String color;
    String brand;

    OS os;
    Charger ref;

    Mobile(String color, String brand) {
        this.color = color;
        this.brand = brand;
        this.os = new OS(32, "Android");
    }
}

public class MobileApp {
    public static void main(String[] args) {
        Mobile mobile = new Mobile("Saffron", "iPhone");

        Charger charger = new Charger("White", "Samsung");

        mobile.ref = charger;

        System.out.println(
            mobile.color + " " + mobile.brand
        );

        System.out.println(
            mobile.os.type + " " + mobile.os.name
        );

        System.out.println(
            mobile.ref.color + " " + mobile.ref.brand
        );
    }
}

public void plugCharger(Charger charger) {
    System.out.println(
        "Charger plugged: "
        + charger.color + " "
        + charger.brand
    );
}

